#!/usr/bin/env bash
# scripts/test_artifact_cli_reference.sh — semantics harness for
# scripts/gen-cli-reference.sh (audit B27).
#
# The chapter is regenerated by staging it in $TMPDIR and moving it into the
# repository. A move across filesystems is NOT a rename: rename(2) fails with
# EXDEV and the kernel falls back to copy + unlink, so a failure in the middle
# of the move left the tracked chapter truncated — half the old narrative and
# half the new help block, which is still a plausible-looking chapter.
#
# The contract pinned here:
#   - the staged chapter is written in the CHAPTER'S OWN directory, so the
#     final move is a rename inside one filesystem (proved by running with a
#     $TMPDIR that cannot be used at all, and with a $TMPDIR on another
#     filesystem);
#   - the chapter keeps its readable mode and the hand-written narrative
#     around the managed block survives;
#   - a run that cannot render leaves the chapter byte-identical;
#   - the --check drift gate still fails on a stale chapter and passes on a
#     fresh one.
#
# Style: user-facing messages in Spanish (repo convention for scripts/);
# internal output in English.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SCRIPT="$ROOT/scripts/gen-cli-reference.sh"

# Scratch lives on a real disk, never on the tmpfs of /tmp.
SCRATCH="${WEBSITE_TEST_SCRATCH:-$HOME/.cache/tmp/webfang-artifact-tests}"
mkdir -p "$SCRATCH" || exit 2
case "$(stat -f -c %T "$SCRATCH" 2>/dev/null)" in
  tmpfs | ramfs)
    echo "refusing tmpfs scratch: $SCRATCH" >&2
    exit 2
    ;;
esac
WORKDIR="$(mktemp -d "$SCRATCH/cli-reference.XXXXXX")"
trap 'rm -rf "$WORKDIR"' EXIT

pass=0
fail=0
skip=0

ok() {
  echo "  PASS  $1"
  pass=$((pass + 1))
}

bad() {
  echo "  FAIL  $1"
  fail=$((fail + 1))
}

skip_case() {
  echo "  SKIP  $1"
  skip=$((skip + 1))
}

# A repository fixture: the chapter with its markers, a cargo stub and a fake
# webfang binary whose --help is the managed block's content.
make_fixture() { # <dir>
  local d="$1"
  mkdir -p "$d/docs/src" "$d/stub" "$d/tgt/debug"
  cat >"$d/docs/src/cli-reference.md" <<'CHAPTEREOF'
# CLI Reference

Hand-written narrative that must survive the regeneration.

<!-- CLI-REFERENCE:BEGIN -->
````text
$ webfang --help

stale help block
````
<!-- CLI-REFERENCE:END -->

Trailing hand-written narrative.
CHAPTEREOF
  cat >"$d/stub/cargo" <<'STUBEOF'
#!/usr/bin/env bash
case " $* " in
  *' build '*) echo "stub: cargo build was NOT given real work"; exit 0 ;;
  *) echo "stub cargo: unsupported: $*" >&2; exit 99 ;;
esac
STUBEOF
  chmod +x "$d/stub/cargo"
  printf '#!/usr/bin/env bash\necho "Usage: fixture binary. Not a real help."\n' >"$d/tgt/debug/webfang"
  chmod +x "$d/tgt/debug/webfang"
}

echo "gen-cli-reference.sh"

# --- the staging does not depend on $TMPDIR ---------------------------------
# NEGATION: before the fix, the chapter was staged in $TMPDIR and moved into
# the repository, which across filesystems is a copy and not a rename: a
# failure in the middle of the move left the tracked chapter truncated. These
# cases accept a chapter that depends on $TMPDIR.
# An unusable $TMPDIR used to abort the run at mktemp; the staging belongs to
# the chapter's own directory.
fixture="$WORKDIR/repo"
make_fixture "$fixture"
unusable="$WORKDIR/no-such-tmpdir"
(cd "$fixture" && PATH="$fixture/stub:$PATH" CARGO_TARGET_DIR="$fixture/tgt" TMPDIR="$unusable" bash "$SCRIPT" >/dev/null 2>&1)
rc=$?
if [ "$rc" -eq 0 ]; then
  ok "the run does not depend on \$TMPDIR (rc=$rc)"
else
  bad "the run does not depend on \$TMPDIR (rc=$rc)"
fi
chapter="$fixture/docs/src/cli-reference.md"
if grep -q 'Usage: fixture binary' "$chapter"; then
  ok "the managed block was regenerated"
else
  bad "the managed block was regenerated"
fi
if grep -q 'stale help block' "$chapter"; then
  bad "the stale help block is gone"
else
  ok "the stale help block is gone"
fi
if grep -q 'Hand-written narrative that must survive' "$chapter" &&
  grep -q 'Trailing hand-written narrative' "$chapter"; then
  ok "the hand-written narrative around the block survives"
else
  bad "the hand-written narrative around the block survives"
fi
mode="$(stat -c %a "$chapter" 2>/dev/null || stat -f %Lp "$chapter" 2>/dev/null)"
if [ "$mode" = "644" ]; then
  ok "the chapter keeps its readable mode (644)"
else
  bad "the chapter keeps its readable mode (644) (got: $mode)"
fi
staged="$(find "$fixture/docs/src" -name 'cli-reference.md.stage.*' | tr '\n' ' ')"
if [ -z "$staged" ]; then
  ok "no staging file is left in the chapter directory"
else
  bad "no staging file is left in the chapter directory (found: $staged)"
fi

# --- a $TMPDIR on another filesystem changes nothing ------------------------
if [ -d /dev/shm ] && [ -w /dev/shm ]; then
  fixture="$WORKDIR/repo-crossfs"
  make_fixture "$fixture"
  before="$(find /dev/shm -maxdepth 1 -name 'tmp.*' | wc -l)"
  (cd "$fixture" && PATH="$fixture/stub:$PATH" CARGO_TARGET_DIR="$fixture/tgt" TMPDIR=/dev/shm bash "$SCRIPT" >/dev/null 2>&1)
  rc=$?
  after="$(find /dev/shm -maxdepth 1 -name 'tmp.*' | wc -l)"
  if [ "$rc" -eq 0 ] && grep -q 'Usage: fixture binary' "$fixture/docs/src/cli-reference.md"; then
    ok "a cross-filesystem \$TMPDIR still regenerates the chapter (rc=$rc)"
  else
    bad "a cross-filesystem \$TMPDIR still regenerates the chapter (rc=$rc)"
  fi
  if [ "$before" -eq "$after" ]; then
    ok "nothing is staged in the cross-filesystem \$TMPDIR"
  else
    bad "nothing is staged in the cross-filesystem \$TMPDIR"
  fi
else
  skip_case "a cross-filesystem TMPDIR (no /dev/shm)"
fi

# --- a run that cannot render leaves the chapter byte-identical ------------
fixture="$WORKDIR/repo-unmanaged"
make_fixture "$fixture"
printf '# CLI Reference\n\nNo markers here: this file is not managed.\n' >"$fixture/docs/src/cli-reference.md"
before="$(md5sum "$fixture/docs/src/cli-reference.md" | cut -d' ' -f1)"
(cd "$fixture" && PATH="$fixture/stub:$PATH" CARGO_TARGET_DIR="$fixture/tgt" bash "$SCRIPT" >/dev/null 2>&1)
rc=$?
after="$(md5sum "$fixture/docs/src/cli-reference.md" | cut -d' ' -f1)"
if [ "$rc" -ne 0 ]; then
  ok "an unmanaged chapter aborts the run (rc=$rc)"
else
  bad "an unmanaged chapter aborts the run (rc=$rc)"
fi
if [ "$before" = "$after" ]; then
  ok "the chapter is byte-identical after the aborted run"
else
  bad "the chapter is byte-identical after the aborted run"
fi

# --- the --check drift gate still works -------------------------------------
fixture="$WORKDIR/repo-check"
make_fixture "$fixture"
(cd "$fixture" && PATH="$fixture/stub:$PATH" CARGO_TARGET_DIR="$fixture/tgt" bash "$SCRIPT" >/dev/null 2>&1)
(cd "$fixture" && PATH="$fixture/stub:$PATH" CARGO_TARGET_DIR="$fixture/tgt" bash "$SCRIPT" --check >/dev/null 2>&1)
rc=$?
if [ "$rc" -eq 0 ]; then
  ok "--check accepts a fresh chapter (rc=$rc)"
else
  bad "--check accepts a fresh chapter (rc=$rc)"
fi
sed -i 's/Usage: fixture binary/Stale help text/' "$fixture/docs/src/cli-reference.md"
(cd "$fixture" && PATH="$fixture/stub:$PATH" CARGO_TARGET_DIR="$fixture/tgt" bash "$SCRIPT" --check >/dev/null 2>&1)
rc=$?
if [ "$rc" -ne 0 ]; then
  ok "--check rejects a stale chapter (rc=$rc)"
else
  bad "--check rejects a stale chapter (rc=$rc)"
fi

echo
if [ "$fail" -eq 0 ]; then
  echo "gen-cli-reference.sh: $pass passed, 0 failed, $skip skipped"
  exit 0
fi
echo "gen-cli-reference.sh: $pass passed, $fail failed, $skip skipped"
exit 1
